public static double stringToDecimal(String numString) {
   double result = 0;

   String[] tokens = numString.split("\\.");
   result += Integer.parseInt(tokens[0]);

   int power = 1;
   for (int i = tokens[1].length(); i > 0; i--) {
        power *= 10;
        result += Integer.parseInt(tokens[1].charAt(i - 1) +"") * 1.0 / power;
   }

