int diffMaxMin(int arr[], int n) 
{ 
    int max_num = arr[0], min_num = arr[0]; 

    int i; 
    for (i = 0; i < n; i++) { 
        max_num = max_num > arr[i] ? max_num : arr[i]; 
        min_num = min_num < arr[i] ? min_num : arr[i]; 
    } 

    return (max_num - min_num); 
} 

