    int temp;

    for (int i = 0; i < array.length; i++) { 
    for (int j = 0; j < array.length; j++) { 
      if (array[j] > array[i]) { 
        temp = array[i]; 
        array[i] = array[j]; 
        array[j] = temp; 
      }
    } 
  }
