public static void selectionSort(int[] arr) { 
    int n = arr.length; 

    for (int i = 0; i < n-1; i++) 
    { 
        int min_idx = i; 
        for (int j = i+1; j < n; j++) 
            if (arr[j] < arr[min_idx]) 
                min_idx = j; 

        int temp = arr[min_idx]; 
        arr[min_idx] = arr[i]; 
        arr[i] = temp; 
    } 
}

function sortArray(arr) {
    let len = arr.length;
    for(let i = len-1; i>=0; i--){
        for(let j = 1; j<=i; j++){
            if(arr[j-1] > arr[j]){
                let temp = arr[j-1];
                arr[j-1] = arr[j];
                arr[j] = temp;
            }
        }
    }
    return arr;
}

