public static int maxSubArraySum(int a[]) 
{ 
    int size = a.length; 
    int maxSoFar = Integer.MIN_VALUE, maxEndingHere = 0; 

    for (int i = 0; i < size; i++) 
    { 
        maxEndingHere = maxEndingHere + a[i]; 
        if (maxSoFar < maxEndingHere) 
            maxSoFar = maxEndingHere; 
        if (maxEndingHere < 0) 
            maxEndingHere = 0; 
    } 
    return maxSoFar; 
}

