def most_frequent(nums):
    # Initialize a dictionary to count the frequency 
    # of each number in the list
    count = {}

    # Iterate through the list and increase the 
    # count of each number in the dictionary
    for num in nums:
        if num> 100:
            if num not in count:
                count[num] = 1
            else:
                count[num] += 1

    # Find the most frequent number
    max_count = 0
    most_frequent_num = 0
    for k,v in count.items():
        if v> max_count:
            most_frequent_num = k
            max_count = v
    return most_frequent_num

function trueFalseRatio(arr){
    let trueCount = 0;
    let falseCount = 0;

    arr.forEach(val => {
        if(val === 0){
            falseCount++;
        } else {
            trueCount++;
        }
    });
    return {
        true: trueCount, 
        false: falseCount
    };
}

